<script setup lang="ts">
import { reactive,ref } from 'vue'
import { ElMessage } from 'element-plus'
import { orderServiceApi } from '@/api/orderService'
const form=reactive<any>({customerId:null,productId:null,packageId:null,effectiveAt:null,expireAt:null,deliveryMode:'SELF_OWNED',externalPurchaseId:null,reverseProxyId:null,remark:''}),result=ref<any>(null),loading=ref(false),data=(r:any)=>r.data.data
async function submit(){if(!form.customerId||!form.productId){ElMessage.warning('请填写客户ID和产品ID');return}loading.value=true;try{result.value=data(await orderServiceApi.manualProvision(form));ElMessage.success('服务开通完成')}finally{loading.value=false}}
</script><template><div class="page"><div><h2>服务开通</h2><p>支持自有资源 SELF_OWNED 与外部反向代理 EXTERNAL_PROXY 两种交付方式。</p></div><el-card shadow="never" v-loading="loading"><el-form label-width="120px" style="max-width:760px"><el-form-item label="客户ID" required><el-input-number v-model="form.customerId" :min="1"/></el-form-item><el-form-item label="产品ID" required><el-input-number v-model="form.productId" :min="1"/></el-form-item><el-form-item label="套餐ID"><el-input-number v-model="form.packageId" :min="1"/></el-form-item><el-form-item label="交付方式"><el-radio-group v-model="form.deliveryMode"><el-radio-button value="SELF_OWNED">自有资源</el-radio-button><el-radio-button value="EXTERNAL_PROXY">外部反向代理</el-radio-button></el-radio-group></el-form-item><template v-if="form.deliveryMode==='EXTERNAL_PROXY'"><el-form-item label="外部采购ID"><el-input-number v-model="form.externalPurchaseId" :min="1"/></el-form-item><el-form-item label="反向代理ID"><el-input-number v-model="form.reverseProxyId" :min="1"/></el-form-item></template><el-form-item label="生效时间"><el-date-picker v-model="form.effectiveAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="到期时间"><el-date-picker v-model="form.expireAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item><el-form-item><el-button type="primary" @click="submit">开通服务</el-button></el-form-item></el-form></el-card><el-alert v-if="result" type="success" :closable="false" title="服务已创建"><pre>{{JSON.stringify(result,null,2)}}</pre></el-alert></div></template><style scoped>.page{display:grid;gap:16px}h2{margin:0 0 6px}p{margin:0;color:#7b8494}pre{white-space:pre-wrap}</style>